import{z as l,x as d,o as s,c as B,q as t,j as i,D as o,d as e,s as A,S as n,b as r}from"./chunks/framework.C8m1ZpeB.js";const I=JSON.parse('{"title":"总线与 MMIO","description":"","frontmatter":{"title":"总线与 MMIO","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bus-mmio.md","filePath":"cs/bus-mmio.md","lastUpdated":1791063341000}'),p={name:"cs/bus-mmio.md"};function c(m,a,D,M,h,u){const E=d("Mermaid");return s(),B("div",null,[a[2]||(a[2]=t('<h1 id="总线与-mmio" tabindex="-1">总线与 MMIO <a class="header-anchor" href="#总线与-mmio" aria-label="Permalink to &quot;总线与 MMIO&quot;">​</a></h1><div class="epigraph"><p>CPU 的访存口接到一组共享地址/数据/控制线上；一段物理地址不对应 DRAM 单元，而对应外设寄存器，这就是内存映射 I/O。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/multicycle-microcode">多周期与微程序直觉</a>让硬件能把指令拆拍执行。本课不重画 FSM 状态，也不从操作系统驱动模型另起。缺口是：到现在「数据存储器」还是一块匿名阵列。真实系统里，同一套 <code>lw</code>/<code>sw</code> 还要打到<strong>外设</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>总线：地址、数据、读/写、就绪。主设备（CPU）发起，从设备（存储控制器、UART）译码地址片选。MMIO：物理地址区间译到设备寄存器，软件仍用 load/store，没有单独 <code>in</code>/<code>out</code>（x86 端口 I/O 是另一风格，本栏不用）。缺口不是新的 ISA 运算，而是地址译码把空间切开。</p><p>就绪信号让慢设备插入等待拍，与多周期「等存储器」同一机制。教学单周期常假装一拍完成。</p><p><span class="marginnote">直觉类比：就绪信号像柜台叫号——CPU 是顾客，慢设备是慢柜台；没叫号（ready 未置位）时总线原地插等待拍，CPU 只能等，不能先拿走还没打好的单据。</span></p><h3 id="mmio-不是「另一套指令集」" tabindex="-1">MMIO 不是「另一套指令集」 <a class="header-anchor" href="#mmio-不是「另一套指令集」" aria-label="Permalink to &quot;MMIO 不是「另一套指令集」&quot;">​</a></h3><p>外设寄存器的比特语义是设备规定的，但访问就是普通 <code>lw</code>/<code>sw</code>。把 MMIO 当成需要新 opcode 的 I/O 指令，RISC-V 的 load/store 原则会破。缓存：MMIO 区通常不可缓存，否则写缓冲会打乱设备顺序——体系结构课再钉，本课承认「有的地址不是 RAM」。</p><p><span class="marginnote">Patterson/Hennessy 用内存映射设备。Harris 有简单总线时序。三态/互斥驱动已在<a href="/cs/transmission-tristate">传输门与三态</a>。本课不把 PCIe 层次写完。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>CPU 发出地址。译码：落在 RAM 则进 DRAM/SRAM 控制器；落在 <code>0x10000000</code> 一类窗口则进 UART 等。设备把寄存器接到总线数据。轮询：软件读状态位。中断通知留到后课入口与 PLIC。</p><p><span class="marginnote">术语翻译：MMIO 就是把设备寄存器「伪装」成内存地址——软件照常 load/store，地址译码器却把这次访问引向 UART 而不是 DRAM，指令集层面看不出任何区别。</span></p>',13)),(s(),i(n,null,{default:o(()=>[A(E,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20CPU%5B%22CPU%20load%2Fstore%22%5D%20--%3E%20BUS%5B%22%E5%9C%B0%E5%9D%80%E6%95%B0%E6%8D%AE%E6%8E%A7%E5%88%B6%22%5D%0A%20%20BUS%20--%3E%20RAM%5B%22%E5%AD%98%E5%82%A8%E5%99%A8%E7%AA%97%E5%8F%A3%22%5D%0A%20%20BUS%20--%3E%20DEV%5B%22%E8%AE%BE%E5%A4%87%E5%AF%84%E5%AD%98%E5%99%A8%E7%AA%97%E5%8F%A3%22%5D%0A%20%20DEV%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%BD%AF%E4%BB%B6%E8%B0%83%E7%94%A8%E7%BA%A6%E5%AE%9A%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[e("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[e("至此，组成上的处理器能执行任意已定义指令序列，并能用地址访问存储与设备。下一课不再加数据通路方框，而是软件如何用 "),r("code",null,"jal"),e(" 与栈传参——硬件已经够用。DMA 是设备当主设备抢总线，本课点名，机制同仲裁。")],-1)),(s(),i(n,null,{default:o(()=>[A(E,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20LD%5B%22lw%20%E6%89%93%E5%88%B0%20MMIO%20%E5%9C%B0%E5%9D%80%22%5D%20--%3E%20DEC%5B%22%E8%AF%91%E7%A0%81%E9%80%89%E4%B8%AD%E8%AE%BE%E5%A4%87%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20DEC%20--%3E%20RDY%7B%22%E8%AE%BE%E5%A4%87%E5%B0%B1%E7%BB%AA%E4%BA%86%E5%90%97%22%7D%0A%20%20RDY%20--%3E%7C%22%E6%9C%AA%E5%B0%B1%E7%BB%AA%22%7C%20WAIT%5B%22%E6%80%BB%E7%BA%BF%E6%8F%92%E5%85%A5%E7%AD%89%E5%BE%85%E6%8B%8D%22%5D%0A%20%20WAIT%20--%3E%20RDY%0A%20%20RDY%20--%3E%7C%22%E5%B0%B1%E7%BB%AA%22%7C%20DRV%5B%22%E8%AE%BE%E5%A4%87%E9%A9%B1%E5%8A%A8%E6%95%B0%E6%8D%AE%E7%BA%BF%22%5D%0A%20%20DRV%20--%3E%20WB%5B%22%E5%86%99%E5%9B%9E%E7%9B%AE%E7%9A%84%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">常见误区：初学者容易以为读设备寄存器可以像读普通内存一样随便缓存——MMIO 区通常标成不可缓存，每次读都要真打到设备；否则缓存或写缓冲把两次访存合并，设备「状态已变」这件事软件就再也看不见。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 VirtIO、不把网络协议栈请进来。不讨论一致性下 MMIO 的强序。中断号如何汇聚是 PLIC 课。</p><p>后课默认：I/O 是 load/store 到特殊物理地址；总线有等待。下一课 ABI 与栈。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>总线连接 CPU 与从设备；MMIO 用访存指令打设备。</li><li>地址译码区分 RAM 与寄存器。</li><li>硬件已能跑任意指令序列；下一课是软件约定。</li><li>出处：Patterson and Hennessy, COD (RISC-V)；Harris and Harris。</li></ul>',6))])}const P=l(p,[["render",c]]);export{I as __pageData,P as default};
